<script setup lang="ts">
import { Head, Link, router, useForm } from '@inertiajs/vue3'
import AppLayout from '@/layouts/AppLayout.vue'
import { lineStyle } from '@/lib/cut-board-line'
type Tran = { id: number; running_no: number; amount: number; wip_lot: string; wms_lot: string }
type Process = { id: number; qc_date: string; product_type_name: string; product_type_full: string; brand_name: string; shift_desc: string; employee_name: string; amount: number; loss_amount: number; status: string; transactions: Tran[] }
const props = defineProps<{ line: string; process: Process; productTypeName: string; wasteRows: Array<{ id: number; barcode: string; lot: string; amount: number; date: string }>; totalWaste: number; saveUrl: string; finishUrl: string; backUrl: string; printAllUrl: string; csvUrl: string }>()
const form = useForm({ amount: String(props.process.amount), loss_amount: String(props.process.loss_amount) })
function save(onSuccess?: () => void) { form.put(props.saveUrl, { preserveScroll: true, onSuccess }) }
function finish() { if (window.confirm('ยืนยันจบงานคัด สร้าง WIP และล็อกรายการเศษที่ตรงกับเกรดนี้หรือไม่?')) router.post(props.finishUrl, {}, { preserveScroll: true }) }
function dateText(value: string) { return value ? new Date(value).toLocaleDateString('th-TH') : '—' }
</script>
<template>
    <Head :title="`รอบคัด C ${line}`" /><AppLayout :title="`รอบคัด C ${line}`" full-width><main class="flex w-full flex-col gap-5 p-4 lg:p-6">
        <header class="rounded-md border border-[var(--hmi-line)] bg-[var(--hmi-surface)] p-5" :style="lineStyle(line)"><div class="flex flex-wrap items-center justify-between gap-4"><div><div class="tag text-xs text-[var(--hmi-mute)]">CUT BOARD · {{ line }} · {{ process.shift_desc || 'SHIFT' }}</div><h1 class="m-0 text-2xl font-extrabold">{{ process.product_type_name }} · {{ process.product_type_full }}</h1><p class="m-0 mt-1 text-sm">วันที่ {{ dateText(process.qc_date) }} · ผู้คัด {{ process.employee_name }}</p></div><div class="flex flex-wrap gap-2"><Link :href="backUrl" class="hmi-button">กลับรายการ</Link><a v-if="process.status === 'complete'" :href="printAllUrl" target="_blank" class="hmi-button-primary">พิมพ์ป้ายทั้งหมด</a><a v-if="process.status === 'complete'" :href="csvUrl" class="hmi-button">Export CSV</a></div></div></header>
        <section class="grid gap-4 lg:grid-cols-[1fr_1.3fr]">
            <form v-if="process.status === 'in process'" class="rounded-md border border-[var(--hmi-line)] bg-[var(--hmi-screen)] p-5" @submit.prevent="save()"><h2 class="mb-4 text-lg font-bold">ยอดคัด / ของเสีย</h2><label class="mb-4 block text-sm font-semibold">จำนวนคัด (แผ่น)<input v-model="form.amount" type="number" min="1" class="hmi-input mt-1"><small class="text-xs font-normal text-[var(--hmi-mute)]">WIP ที่จับคู่เกรด C ได้: {{ totalWaste.toLocaleString() }} แผ่น</small><small v-if="form.errors.amount" class="block text-red-600">{{ form.errors.amount }}</small></label><label class="mb-4 block text-sm font-semibold">จำนวนเสีย<input v-model="form.loss_amount" type="number" min="0" class="hmi-input mt-1"><small v-if="form.errors.loss_amount" class="block text-red-600">{{ form.errors.loss_amount }}</small></label><div class="flex flex-wrap gap-2"><button class="hmi-button" :disabled="form.processing">บันทึกยอด</button><button type="button" class="hmi-button-primary" :disabled="form.processing || Number(form.amount) < 1" @click="save(() => finish())">ยืนยันจบงาน</button></div><p class="mt-3 text-xs text-[var(--hmi-mute)]">จบงานแล้วระบบแบ่งยอดเป็นล็อตละไม่เกิน 100 แผ่น และทำเครื่องหมาย WIP ที่เข้าเงื่อนไข</p></form>
            <section class="overflow-hidden rounded-md border border-[var(--hmi-line)] bg-[var(--hmi-screen)]"><div class="border-b border-[var(--hmi-line)] bg-[var(--hmi-surface)] p-4"><h2 class="m-0 text-lg font-bold">WIP / เศษที่เข้าเงื่อนไข</h2><p class="m-0 text-xs text-[var(--hmi-mute)]">แสดงรายการไลน์ {{ line }} ที่ยังไม่ถูกใช้และบาร์โค้ดตรงกับชนิดสินค้า</p></div><div class="max-h-96 overflow-auto"><table class="hmi-table"><thead><tr><th>วันที่</th><th>Barcode</th><th>Lot</th><th class="text-right">จำนวน</th></tr></thead><tbody><tr v-for="w in wasteRows" :key="w.id"><td>{{ dateText(w.date) }}</td><td class="font-mono text-xs">{{ w.barcode }}</td><td>{{ w.lot }}</td><td class="text-right">{{ w.amount.toLocaleString() }}</td></tr><tr v-if="!wasteRows.length"><td colspan="4" class="py-8 text-center text-[var(--hmi-mute)]">ไม่มี WIP ที่ยังไม่ใช้สำหรับชนิดสินค้านี้</td></tr></tbody></table></div></section>
        </section>
        <section v-if="process.transactions.length" class="overflow-hidden rounded-md border border-[var(--hmi-line)] bg-[var(--hmi-screen)]"><div class="border-b border-[var(--hmi-line)] bg-[var(--hmi-surface)] p-4"><h2 class="m-0 text-lg font-bold">รายการ WIP ที่สร้างแล้ว</h2></div><table class="hmi-table"><thead><tr><th>ลำดับ</th><th>WIP Lot</th><th>WMS Lot</th><th class="text-right">จำนวน</th><th></th></tr></thead><tbody><tr v-for="t in process.transactions" :key="t.id"><td>{{ t.running_no }}</td><td class="font-mono text-xs">{{ t.wip_lot }}</td><td class="font-mono text-xs">{{ t.wms_lot }}</td><td class="text-right">{{ t.amount }}</td><td><a :href="`${backUrl}/print/${process.id}/${t.id}`" target="_blank" class="hmi-button">พิมพ์ป้าย</a></td></tr></tbody></table></section>
    </main></AppLayout></template>
<style scoped>.hmi-input{display:block;width:100%;min-height:2.6rem;border:1px solid var(--hmi-line);border-radius:.3rem;background:var(--hmi-panel);padding:.55rem;color:var(--hmi-text)}.hmi-button,.hmi-button-primary{display:inline-flex;min-height:2.4rem;align-items:center;justify-content:center;border:1px solid var(--hmi-line);border-radius:.3rem;padding:.45rem .8rem;font-size:.85rem;font-weight:700}.hmi-button{background:var(--hmi-panel)}.hmi-button-primary{background:var(--line-color);border-color:var(--line-color);color:white}.hmi-table{width:100%;border-collapse:collapse;font-size:.85rem}.hmi-table th{background:var(--hmi-panel);text-align:left;font-size:.75rem;color:var(--hmi-mute)}.hmi-table th,.hmi-table td{border-bottom:1px solid var(--hmi-line);padding:.7rem .85rem}</style>
